import React, { useState, useMemo } from 'react';
import { tools, toolCategories } from '../mock';
import {
  BookOpen, FileText, Smartphone, Video, Film, Palette, Pen, Figma,
  Bot, FileCode, Bug, GitBranch, MessageSquare, BarChart3, ChevronDown, Search,
} from 'lucide-react';

const iconMap = {
  BookOpen, FileText, Smartphone, Video, Film, Palette, Pen, Figma,
  Bot, FileCode, Bug, GitBranch, MessageSquare, ChartBar: BarChart3,
};

export default function Toolkit() {
  const [open, setOpen] = useState(true);
  const [category, setCategory] = useState('All Tools');
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState('Name');

  const filtered = useMemo(() => {
    let list = tools.filter((t) =>
      (category === 'All Tools' || t.cat === category) &&
      (t.name.toLowerCase().includes(query.toLowerCase()) ||
        t.desc.toLowerCase().includes(query.toLowerCase()))
    );
    if (sortBy === 'Name') list = [...list].sort((a, b) => a.name.localeCompare(b.name));
    else list = [...list].sort((a, b) => a.cat.localeCompare(b.cat));
    return list;
  }, [category, query, sortBy]);

  return (
    <section id="toolkit" className="px-6 md:px-10 py-20">
      <div className="max-w-7xl mx-auto">
        <div className="section-eyebrow">Professional Toolkit</div>
        <h2 className="font-serif text-4xl md:text-5xl text-neutral-900 mt-3 max-w-4xl leading-tight">
          Tools I use to design, build, and manage learning experiences
        </h2>
        <p className="text-neutral-600 mt-5 max-w-3xl leading-relaxed">
          A scannable view of the platforms, authoring tools, design apps, AI tools, and
          collaboration systems I use across technical education and product learning work.
        </p>

        <button onClick={() => setOpen(!open)} className="mt-6 ghost-btn px-5 py-2.5 text-sm font-medium inline-flex items-center gap-2">
          {open ? 'Hide professional toolkit' : 'Show professional toolkit'}
          <ChevronDown size={14} className={`transition-transform ${open ? 'rotate-180' : ''}`} />
        </button>

        {open && (
          <div className="mt-6">
            <div className="flex flex-wrap items-center gap-2">
              {toolCategories.map((c) => (
                <button
                  key={c}
                  onClick={() => setCategory(c)}
                  className={`text-sm px-4 py-2 rounded-full border border-black/10 bg-white text-neutral-700 hover:bg-neutral-50 transition ${
                    category === c ? 'tab-active' : ''
                  }`}
                >
                  {c}
                </button>
              ))}
              <div className="ml-auto flex items-center gap-3">
                <div className="relative">
                  <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-neutral-400" />
                  <input
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="Search tools"
                    className="pl-8 pr-3 py-2 rounded-full border border-black/10 bg-white text-sm outline-none focus:ring-2 focus:ring-violet-300 w-52"
                  />
                </div>
              </div>
            </div>

            <div className="mt-5 flex items-center justify-between text-sm text-neutral-500">
              <span>Sort by:{' '}
                <button className={`ml-1 ${sortBy === 'Name' ? 'text-violet-600 font-medium' : ''}`} onClick={() => setSortBy('Name')}>Name (A–Z)</button>
                <span className="mx-2 opacity-40">|</span>
                <button className={`${sortBy === 'Category' ? 'text-violet-600 font-medium' : ''}`} onClick={() => setSortBy('Category')}>Category</button>
              </span>
              <span>{filtered.length} tools shown</span>
            </div>

            <div className="mt-5 grid sm:grid-cols-2 lg:grid-cols-4 gap-3">
              {filtered.map((t) => {
                const Icon = iconMap[t.icon] || FileText;
                return (
                  <div key={t.name} className="glass-card rounded-xl p-4 flex items-start gap-3 hover:-translate-y-0.5 transition-transform">
                    <div className="w-9 h-9 rounded-lg flex items-center justify-center bg-violet-50 text-violet-600 shrink-0">
                      <Icon size={18} />
                    </div>
                    <div>
                      <div className="font-medium text-neutral-900 text-[15px]">{t.name}</div>
                      <div className="text-[12.5px] text-neutral-500">{t.desc}</div>
                      <div className="text-[11px] text-violet-600 mt-1 uppercase tracking-wider">{t.cat}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </section>
  );
}
