import React, { useState, useRef } from 'react';
import { Link } from 'react-router-dom';
import { workCategories } from '../mock';
import { titleToSlug } from '../data/slugs';
import { ChevronLeft, ChevronRight, ArrowUpRight } from 'lucide-react';

export default function WorkSamples() {
  const [activeIdx, setActiveIdx] = useState(0);
  const scrollerRef = useRef(null);
  const active = workCategories[activeIdx];

  const scrollBy = (dir) => {
    const el = scrollerRef.current;
    if (!el) return;
    el.scrollBy({ left: dir * 340, behavior: 'smooth' });
  };

  const cardGradients = [
    'linear-gradient(135deg,#eef2ff,#f5eaff)',
    'linear-gradient(135deg,#f0f9ff,#fdf2ff)',
    'linear-gradient(135deg,#fef6ff,#eaf3ff)',
    'linear-gradient(135deg,#f2f7ff,#fff0f6)',
  ];

  return (
    <section id="projects" className="px-6 md:px-10 py-20">
      <div className="max-w-7xl mx-auto">
        <div className="section-eyebrow">Work Samples &amp; Projects</div>
        <h2 className="font-serif text-4xl md:text-5xl text-neutral-900 mt-3">Work Samples &amp; Projects</h2>
        <p className="text-neutral-600 mt-5 max-w-4xl leading-relaxed">
          This portfolio includes publicly available work, generalized case studies, independent
          redesigns, and original learning samples. Some projects are based on work I contributed
          to at Dell Technologies, Infosys, and iNurture and are shared for portfolio demonstration
          only. Company-specific details, internal data, and confidential materials have been
          removed or generalized.
        </p>

        <div className="mt-8 glass-card rounded-full p-1.5 flex items-center gap-1 overflow-x-auto no-scrollbar">
          {workCategories.map((c, i) => (
            <button
              key={c.id}
              onClick={() => setActiveIdx(i)}
              className={`whitespace-nowrap text-sm px-4 py-2 rounded-full border border-transparent text-neutral-700 hover:bg-white transition ${
                i === activeIdx ? 'tab-active' : ''
              }`}
            >
              <span className={`mr-2 text-xs font-mono ${i === activeIdx ? 'opacity-90' : 'text-violet-500'}`}>
                0{i + 1}
              </span>
              {c.tabLabel}
            </button>
          ))}
        </div>

        <div className="mt-8 glass-card rounded-3xl p-7 relative overflow-hidden">
          <div className="absolute top-6 right-8 font-serif text-6xl text-violet-100 select-none">
            0{activeIdx + 1}
          </div>
          <h3 className="font-serif text-2xl md:text-3xl text-neutral-900 max-w-3xl leading-tight">
            {active.title}
          </h3>
          <p className="text-neutral-600 mt-3 max-w-3xl leading-relaxed">
            {active.description} <strong className="text-neutral-900">{active.count}.</strong>
          </p>
        </div>

        {active.samples.length > 3 && (
          <div className="mt-6 flex items-center justify-between">
            <p className="text-sm text-neutral-500">
              Use previous and next buttons or scroll horizontally to browse all {active.samples.length} samples.
            </p>
            <div className="flex gap-2">
              <button onClick={() => scrollBy(-1)} className="ghost-btn w-9 h-9 flex items-center justify-center">
                <ChevronLeft size={16} />
              </button>
              <button onClick={() => scrollBy(1)} className="ghost-btn w-9 h-9 flex items-center justify-center">
                <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        <div ref={scrollerRef} className="mt-6 flex gap-4 overflow-x-auto no-scrollbar pb-2 snap-x">
          {active.samples.map((s, i) => (
            <article
              key={s.title}
              className="glass-card rounded-2xl min-w-[300px] md:min-w-[340px] flex-1 snap-start overflow-hidden group hover:-translate-y-1 transition-transform duration-300"
            >
              <div className="h-40 relative" style={{ background: cardGradients[i % cardGradients.length] }}>
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-40 h-24 rounded-xl bg-white/80 shadow-sm flex flex-col justify-center px-4">
                    <div className="h-1.5 w-16 rounded-full bg-violet-300 mb-2" />
                    <div className="h-1 w-24 rounded-full bg-blue-200 mb-1.5" />
                    <div className="h-1 w-20 rounded-full bg-pink-200" />
                  </div>
                </div>
              </div>
              <div className="p-5">
                <h4 className="font-serif text-lg text-neutral-900 leading-snug">{s.title}</h4>
                <p className="text-[13px] text-neutral-600 mt-2 leading-relaxed">
                  <span className="text-neutral-800 font-medium">Strategy lens:</span> {s.lens}
                </p>
                <p className="text-[14px] text-neutral-700 mt-2 leading-relaxed">{s.summary}</p>
                <div className="mt-4 flex items-center justify-between">
                  <span className="chip">{s.chip}</span>
                  {titleToSlug[s.title] ? (
                    <Link to={`/projects/${titleToSlug[s.title]}`} className="text-sm font-medium text-violet-600 inline-flex items-center gap-1 group-hover:gap-2 transition-all">
                      View <ArrowUpRight size={14} />
                    </Link>
                  ) : (
                    <button className="text-sm font-medium text-violet-600 inline-flex items-center gap-1 group-hover:gap-2 transition-all">
                      View <ArrowUpRight size={14} />
                    </button>
                  )}
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
