import React, { useState, useEffect } from 'react';
import { profile } from '../mock';

const links = [
  { href: '#about', label: 'About' },
  { href: '#how', label: 'How I Work' },
  { href: '#ecosystem', label: 'Ecosystem' },
  { href: '#projects', label: 'Work Samples' },
  { href: '#resources', label: 'Resources' },
  { href: '#toolkit', label: 'Toolkit' },
  { href: '#certs', label: 'Certifications' },
  { href: '#contact', label: 'Contact' },
];

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 inset-x-0 z-40 transition-all duration-300 ${
        scrolled ? 'bg-white/70 backdrop-blur-md border-b border-black/5' : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-10 h-16 flex items-center justify-between">
        <a href="#top" className="flex items-center gap-3">
          <span className="w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-bold"
            style={{ background: 'linear-gradient(135deg,#6d5df6,#4aa9ff)' }}>
            {profile.initials}
          </span>
          <span className="font-semibold text-neutral-900 tracking-tight">{profile.name}</span>
        </a>
        <nav className="hidden lg:flex items-center gap-7">
          {links.map((l) => (
            <a key={l.href} href={l.href} className="text-sm text-neutral-700 hover:text-neutral-900 link-underline">
              {l.label}
            </a>
          ))}
        </nav>
        <button className="lg:hidden text-neutral-800" onClick={() => setOpen(!open)} aria-label="menu">
          <div className="space-y-1.5">
            <span className="block w-6 h-0.5 bg-neutral-800" />
            <span className="block w-6 h-0.5 bg-neutral-800" />
            <span className="block w-4 h-0.5 bg-neutral-800" />
          </div>
        </button>
      </div>
      {open && (
        <div className="lg:hidden bg-white/95 backdrop-blur border-t border-black/5">
          <div className="px-6 py-4 grid gap-3">
            {links.map((l) => (
              <a key={l.href} href={l.href} onClick={() => setOpen(false)} className="text-sm text-neutral-800 py-1">
                {l.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </header>
  );
}
