import { jsPDF } from 'jspdf';
import { profile, experience, certifications } from '../mock';

export function generateResumePDF() {
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });
  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  const margin = 48;
  let y = margin;

  const ensureSpace = (h) => {
    if (y + h > pageH - margin) {
      doc.addPage();
      y = margin;
    }
  };

  // Header
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(24);
  doc.setTextColor(23, 23, 23);
  doc.text(profile.name, margin, y);
  y += 22;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(11);
  doc.setTextColor(90, 90, 100);
  doc.text(profile.subtitle, margin, y);
  y += 16;

  doc.setFontSize(10);
  doc.setTextColor(109, 93, 246);
  const contactLine = `${profile.email}  \u2022  ${profile.linkedin}  \u2022  ${profile.github}  \u2022  ${profile.location}`;
  doc.text(contactLine, margin, y);
  y += 20;

  // Divider
  doc.setDrawColor(220, 220, 230);
  doc.line(margin, y, pageW - margin, y);
  y += 16;

  // Summary
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(12);
  doc.setTextColor(23, 23, 23);
  doc.text('SUMMARY', margin, y);
  y += 14;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10.5);
  doc.setTextColor(60, 60, 70);
  const summary = doc.splitTextToSize(profile.tagline, pageW - margin * 2);
  doc.text(summary, margin, y);
  y += summary.length * 13 + 10;

  // Experience
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(12);
  doc.setTextColor(23, 23, 23);
  doc.text('PROFESSIONAL EXPERIENCE', margin, y);
  y += 14;

  experience.forEach((e) => {
    ensureSpace(60);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(23, 23, 23);
    doc.text(e.role, margin, y);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(109, 93, 246);
    doc.text(e.period, pageW - margin, y, { align: 'right' });
    y += 13;
    doc.setFontSize(10.5);
    doc.setTextColor(90, 90, 100);
    doc.setFont('helvetica', 'italic');
    doc.text(e.company, margin, y);
    y += 12;
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(60, 60, 70);
    e.bullets.forEach((b) => {
      const lines = doc.splitTextToSize(`\u2022  ${b}`, pageW - margin * 2 - 10);
      ensureSpace(lines.length * 12 + 4);
      doc.text(lines, margin + 8, y);
      y += lines.length * 12 + 2;
    });
    y += 6;
  });

  // Certifications
  ensureSpace(60);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(12);
  doc.setTextColor(23, 23, 23);
  doc.text('CERTIFICATIONS', margin, y);
  y += 14;
  certifications.forEach((c) => {
    ensureSpace(32);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10.5);
    doc.setTextColor(23, 23, 23);
    doc.text(c.title, margin, y);
    y += 12;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(90, 90, 100);
    doc.text(c.org, margin, y);
    y += 12;
    doc.setTextColor(60, 60, 70);
    const d = doc.splitTextToSize(c.desc, pageW - margin * 2);
    ensureSpace(d.length * 11 + 6);
    doc.text(d, margin, y);
    y += d.length * 11 + 6;
  });

  // Footer
  const pages = doc.getNumberOfPages();
  for (let i = 1; i <= pages; i++) {
    doc.setPage(i);
    doc.setFontSize(9);
    doc.setTextColor(160, 160, 170);
    doc.text(`${profile.name} \u2014 Resume \u2014 Page ${i} of ${pages}`, pageW / 2, pageH - 24, { align: 'center' });
  }

  doc.save('Sriprajna-KJ-Resume.pdf');
}
